    [Xunit.Fact]
    public static void TestPercentFamilyRequiresIncumbentSupportBeforeACrop() {
        emon.Port.Cells text = emon.Port.NewCells();
        emon.Port.Cells words = emon.Port.NewCells();
        emon.Port.Cells rows = emon.Port.NewCells();
        emon.Port.Cells plan = emon.Port.NewCells();
        emon.Port.Cells am = emon.Port.NewCells();
        emon.Port.Cells bm = emon.Port.NewCells();
        emon.Port.Cells pm = emon.Port.NewCells();
        PcttWords(text, words);
        emon.Testport.AssertEq(Oapct.PctRows(words, text, 0, 15, rows, am, bm, pm), 5, "five complete geometric rows");
        emon.Testport.AssertEq(emon.Port.CellsAt(rows, 3), 1, "first identity closes on incumbents");
        emon.Testport.AssertEq(emon.Port.CellsAt(rows, 19), 0, "the positive sign fails the negative change");
        emon.Testport.AssertEq(Oapct.PctPlan(words, rows, plan), 4, "one supported failing cell gets a crop");
        emon.Testport.AssertEq(emon.Port.CellsAt(plan, 0), 14, "only the failing percent slot");
        emon.Testport.AssertEq(emon.Port.CellsAt(plan, 2), 4, "four incumbent identities support the family");
        emon.Port.CellsSet(rows, 3, 0);
        emon.Testport.AssertEq(Oapct.PctPlan(words, rows, plan), 0, "three holds cannot authorize a crop");
    }
