        emon.Port.Cells pm = emon.Port.NewCells();
        int w = 15;
        int x = 0;
        PcttWords(text, words);
        PcttWords(text, words);
        while (w < 30) {
            x = Evidence.OwGet(words, w, Evidence.HdX0()) + 900;
            Evidence.OwSet(words, w, Evidence.HdX0(), x);
            x = Evidence.OwGet(words, w, Evidence.HdX1()) + 900;
            Evidence.OwSet(words, w, Evidence.HdX1(), x);
