    [Xunit.Fact]
    public static void TestThreeTimesCropFilterPreservesFlatGrayAndCentralInk() {
        emon.Port.BitmapSet bms = emon.Port.NewBitmapSet();
        emon.Port.Bitmap src = emon.Port.BmsPut(bms, 1, 9, 1, 1);
        int x = 0;
        while (x < 9) {
            emon.Port.BitmapSetU8(src, x, 0, 0, 120);
            x += 1;
        }
        Oacrop.OaThree(bms, 2, 3, src);
        emon.Port.Bitmap flat = emon.Port.BmsGet(bms, 2);
        emon.Testport.AssertEq(emon.Port.BitmapW(flat), 27, "integer x3 width");
        emon.Testport.AssertEq(emon.Port.BitmapH(flat), 3, "integer x3 height");
        emon.Testport.AssertEq(emon.Port.BitmapU8(flat, 13, 1, 0), 120, "normalized coefficients preserve flat gray");
        x = 0;
        while (x < 9) {
            emon.Port.BitmapSetU8(src, x, 0, 0, 255);
            x += 1;
        }
        emon.Port.BitmapSetU8(src, 4, 0, 0, 0);
        Oacrop.OaThree(bms, 4, 5, src);
        emon.Port.Bitmap ink = emon.Port.BmsGet(bms, 4);
        emon.Testport.AssertEq(emon.Port.BitmapU8(ink, 13, 1, 0), 0, "source-center phase preserves black ink");
        emon.Testport.AssertEq(emon.Port.BitmapU8(ink, 12, 1, 0), 47, "independent Lanczos sample left of the central stroke");
        emon.Testport.AssertEq(emon.Port.BitmapU8(ink, 14, 1, 0), 47, "symmetric sample right of the central stroke");
    }
